        """
        Queries data from a /<security_type>/points endpoint.

        Args:
            security_symbols (list): List of string symbols
            calculation_codes (list): List og string calculation codes
            query_date
                (datetime): datetime object on or before which the endpoint will query data for.
                (int): Negative integer representing relative periods(as it relates to each calc code) in the past.

        Returns:
            dict of the decoded json from server response.

        Notes:
            The max length of any list arg is 100
        """
           pandas.DataFrame: DataFrame of points data
        """
        if query_date is None:
            query_date = self.current_date

        if isinstance(query_date, int):
            query_date = self.current_date - timedelta(days=query_date)

        if isinstance(query_date, datetime):
            query_date = query_date.strftime("%Y-%m-%d")

        if isinstance(security_symbols, str):
            security_symbols = [security_symbols]

        if isinstance(calculation_codes, str):
            calculation_codes = [calculation_codes]

        if not isinstance(security_symbols, list):
            raise ValueError("security_symbols must be a list of strings")

        if not isinstance(calculation_codes, list):
            raise ValueError("calculation_codes must be a list of strings")

        if not isinstance(query_date, str):
            raise ValueError("query_date must be a string")

        if not security_symbols:
            raise ValueError("security_symbols must not be empty")

        if not calculation_codes:
            raise ValueError("calculation_codes must not be empty")

        if len(security_symbols) != len(calculation_codes):
            raise ValueError(
                "security_symbols and calculation_codes must be the same length"
            )

        params = {
            "security_symbols": ",".join(security_symbols),
            "calculation_codes": ",".join(calculation_codes),
            "query_date": query_date,
        }

        return self._get_points(params)

