def create(cls, community, record, user=None, expires_at=None,
               notify=True):
        """Create a record inclusion request to a community.

        :param community: Community object.
        :param record: Record API object.
        :param expires_at: Time after which the request expires and shouldn't
            be resolved anymore.
        """
            if not user:
                user = flask.g.get('user', None)
            if not user:
                raise exceptions.NeedLogin()

            if not record.can_be_requested_by(user):
                raise exceptions.NeedPermission()

            if record.is_in_community(community):
                raise exceptions.AlreadyIncluded()

            if record.is_requested_in_community(community):
                raise exceptions.AlreadyRequested()

            request = cls(
                community=community,
                record=record,
                user=user,
                expires_at=expires_at,
            )
            db.session.add(request)
            db.session.commit()

            if notify:
                request.notify()

            return request

