def get_link(cls, source, target, topology=None):
        """
        Find link between source and target, (or vice versa, order is irrelevant).
        :param source: ip or mac addresses
        :param target: ip or mac addresses
        :param topology: optional topology relation
        :returns: Link object
        :raises: LinkNotFound
        """
            if topology is None:
                topology = cls.get_topology()
            if source not in topology:
                raise LinkNotFound('Source %s not found in topology' % source)
            if target not in topology:
                raise LinkNotFound('Target %s not found in topology' % target)
            for link in topology[source]:
                if link.target == target:
                    return link
            for link in topology[target]:
                if link.source == source:
                    return link
            raise LinkNotFound('Link between %s and %s not found' % (source, target))

