def find_closest_in_list(number, array, direction="both", strictly=False):
    """
    Find the closest number in the array from x.

    Parameters
    ----------
    number : float
        The number.
    array : list
        The list to look in.
    direction : str
        "both" for smaller or greater, "greater" for only greater numbers and "smaller" for the closest smaller.
    strictly : bool
        False for stricly superior or inferior or True for including equal.

    Returns
    ----------
    closest : int
        The closest number in the array.

    Example
    ----------
    >>> import neurokit as nk
    >>> nk.find_closest_in_list(1.8, [3, 5, 6, 1, 2])

    Notes
    ----------
    *Authors*

    - `Dominique Makowski <https://dominiquemakowski.github.io/>`_

    """
    Returns
        -------
        float
            The closest number.

        """
        if direction == "both":
            if strictly:
                return min(array, key=lambda x: abs(x - number))
            else:
                return min(array + [number], key=lambda x: abs(x - number))
        elif direction == "greater":
            if strictly:
                return max(array, key=lambda x: abs(x - number))
            else:
                return max(array + [number], key=lambda x: abs(x - number))
        elif direction == "smaller":
            if strictly:
                return min(array, key=lambda x: abs(x - number))
            else:
                return min(array + [number], key=lambda x: abs(x - number))
        else:
            raise ValueError("direction must be 'both', 'greater' or 'smaller'")

