def fwd(self, astr_startPath, **kwargs):
            """
            Return the files-in-working-directory in treeRecurse
            compatible format.
            :return: Return the cwd in treeRecurse compatible format.
            """
            status = self.cd(astr_startPath)['status']
            if status:
