        model.addCons(x[j,k] + x[k,j] == 1, "Disjunctive(%s,%s)"%(j,k))

        for ell in J:
            if ell > k:
                model.addCons(x[j,k] + x[k,ell] + x[ell,j] <= 2, "Triangle(%s,%s,%s)"%(j,k,ell))

model.setObjective(quicksum(w[j]*T[j] for j in J), "minimize")


model.data = x,T
return model

