      # End deletion
      cigar.append("-%s"%''.join(deletion))
      deletion = []
   if gap_ref:
      if insertion:
         # Extend insertion
         insertion.append(q_aa)
      else:
         # Start insertion
         insertion = [q_aa]
   elif gap_que:
      if deletion:
         # Extend deletion
         deletion.append(r_aa)
      else:
         # Start deletion
         deletion = [r_aa]
   elif match:
      if matches:
         # Extend match block
         matches.append(r_aa)
      else:
         # Start match block
         matches = [r_aa]
   else:
      # Add SNP annotation
      cigar.append("*%s%s"%(r_aa, q_aa))

if matches:
