def check_version(module_version, version, installed_version=None):
    """
    Return True if module version is satisfied

    version may starts with =, >=, > or < to specify the exact requirement ;
    multiple conditions may be separated by ';' (e.g. '>=0.13;<1.0')

    Return False if version is not satisfied
    """
    if installed_version is not None:
        module_version = installed_version
    if version.startswith('='):
        return module_version == version[1:]
    elif version.startswith('>='):
        return module_version >= version[2:]
    elif version.startswith('>'):
        return module_version > version[1:]
    elif version.startswith('<'):
        return module_version < version[1:]
    elif version.startswith('<='):
        return module_version <= version[2:]
