def read(self) :
	"""reads the file and returns the data"""
	self.file.seek(0)
	return self.file.read()

def close(self) :
	"""closes the file"""
	self.file.close()

def __del__(self) :
	"""destructor"""
	self.close()

def __enter__(self) :
	"""context manager"""
	return self

def __exit__(self, exc_type, exc_val, exc_tb) :
	"""context manager"""
	self.close()

def __str__(self) :
	"""string representation"""
	return self.read()

def __repr__(self) :
	"""representation"""
	return self.read()

def __len__(self) :
	"""length of the file"""
	return len(self.read())

def __getitem__(self, key) :
	"""get item"""
	return self.read()[key]

def __setitem__(self, key, value) :
	"""set item"""
	self.file.seek(0)
	self.file.write(value)
	self.file.flush()

def __delitem__(self, key) :
	"""delete item"""
	self.file.seek(0)
	self.file.truncate(key)
	self.file.flush()

def __iter__(self) :
